import kotlin.concurrent.thread

// Not real Android. Thread.sleep stands for a slow job.
fun loadReport(): String {
    Thread.sleep(300)
    return "report ready"
}

fun main() {
    println("Screen: drawing")
    var report = ""
    val helper = thread(name = "helper") {
        report = loadReport()
    }
    println("Screen: still drawing")
    helper.join()
    println("Job: " + report)
}
